options.onCreated:
const s=this.vueState;const field=this;
const PROCESS_ID='6a7e787e8d398c11cf2fe8b8';const WORK_ITEM_PROCESS_ID='6a7e82ba8d398c11cf2fe8d5';
s.rows=[];s.search='';s.view='waiting';s.loading=false;s.info='';s.updatingIds={};
s.safeArray=v=>{try{const x=typeof v==='string'?JSON.parse(v||'[]'):(v||[]);return Array.isArray(x)?x:[]}catch(e){return []}};
s.state=row=>{const v=String((row&&row.specimen_status)||'waiting').toLowerCase();return v==='collected'||v==='sent'?v:'waiting'};
s.stateLabel=row=>{const x=s.state(row);return x==='collected'?'รอส่งสิ่งส่งตรวจ':x==='sent'?'ส่งสิ่งส่งตรวจแล้ว':'รอรับสิ่งส่งตรวจ'};
s.patient=row=>({patient_hn:row&&row.patient_hn,patient_name:row&&row.patient_name});
s.initial=row=>{const p=s.patient(row);const x=String((p&&p.patient_name)||(row&&row.order_number)||'?').trim();return x?x.charAt(0).toUpperCase():'?'};
s.items=row=>s.safeArray(row&&row.selected_items);
s.itemCount=row=>s.items(row).length;
s.specimens=row=>{const list=s.safeArray(row&&row.specimens);const seen={};return list.map(x=>String(x.label||x.specimen_name||x.specimen_code||'ไม่ระบุ specimen')).filter(x=>{if(seen[x])return false;seen[x]=true;return true}).join(' · ')||'-'};
s.time=v=>{if(!v)return '-';try{return new Date(v).toLocaleString('th-TH',{dateStyle:'short',timeStyle:'short'})}catch(e){return String(v)}};
s.setSearch=v=>{s.search=String(v||'')};
s.selectTab=name=>{s.view=name};
s.filteredBy=status=>{const q=s.search.trim().toLowerCase();return (s.rows||[]).filter(r=>{if(s.state(r)!==status)return false;if(!q)return true;const p=s.patient(r);return [p.patient_hn,p.patient_name,r.order_number,r.section_name].join(' ').toLowerCase().includes(q)})};
s.errMsg=err=>{if(!err)return '';if(typeof err==='string')return err;return err.message||(err.reply&&err.reply.message)||(err.data&&err.data.message)||''};
s.callProcess=(api,params,onOk,onFail)=>{let settled=false;const ok=res=>{if(settled)return;settled=true;onOk(res)};const bad=err=>{if(settled)return;settled=true;onFail(err)};try{api.runProcess(PROCESS_ID,params,ok,bad)}catch(e){bad(e)}};
s.load=()=>{const form=field.getFormRef&&field.getFormRef(),api=(form&&form.userState)||field.globalUserState;if(!api||typeof api.runProcess!=='function'){s.rows=[];s.info='โหลดไม่สำเร็จ';field.notify('ไม่พบ API connector','error',4500);return}s.loading=true;s.info='กำลังโหลดรายการ...';s.callProcess(api,{action:'list'},res=>{s.loading=false;const body=(res&&res.data)||{};if(!body.success){s.rows=[];s.info='โหลดไม่สำเร็จ';field.notify('โหลดรายการไม่สำเร็จ: '+(body.message||''),'error',4500);return}s.rows=body.rows||[];s.info='พบ '+s.rows.length+' รายการ'},err=>{s.loading=false;s.rows=[];s.info='โหลดไม่สำเร็จ';field.notify('โหลดรายการไม่สำเร็จ: '+(s.errMsg(err)||'ตรวจสอบการเชื่อมต่อ API'),'error',4500)})};
s.updateStatus=(row,nextStatus,doneMsg,afterUpdate)=>{const form=field.getFormRef&&field.getFormRef(),api=(form&&form.userState)||field.globalUserState;if(!api||typeof api.runProcess!=='function'){field.notify('ไม่พบ API connector','error',3500);return}const id=row._id||row.id;if(s.updatingIds[id])return;s.updatingIds={...s.updatingIds,[id]:true};const finish=()=>{const u={...s.updatingIds};delete u[id];s.updatingIds=u};const complete=()=>{finish();field.notify(doneMsg,'success',2500);s.load()};s.callProcess(api,{action:'update',order_number:row.order_number,status:nextStatus},res=>{const body=(res&&res.data)||{};if(!body.success){finish();field.notify('บันทึกไม่สำเร็จ: '+(body.message||''),'error',4000);return}if(typeof afterUpdate==='function'){afterUpdate(api,complete)}else complete()},err=>{finish();field.notify('บันทึกไม่สำเร็จ: '+(s.errMsg(err)||'ตรวจสอบการเชื่อมต่อ API'),'error',4000)})};
s.receive=row=>s.updateStatus(row,'collected','รับสิ่งส่งตรวจแล้ว');
s.send=row=>s.updateStatus(row,'sent','ส่งสิ่งส่งตรวจแล้ว',(api,complete)=>{const snapshot={...row,specimen_status:'sent'},id=row._id||row.id,failed=message=>{const u={...s.updatingIds};delete u[id];s.updatingIds=u;field.notify('ส่งสิ่งส่งตรวจแล้ว แต่สร้าง Lab Work Item ไม่สำเร็จ: '+message,'error',5000);s.load()};try{api.runProcess(WORK_ITEM_PROCESS_ID,{source_record:snapshot},res=>{const body=(res&&res.data)||{};if(body.success===false){failed(body.message||'');return}complete()},err=>failed(s.errMsg(err)||''))}catch(e){failed(s.errMsg(e)||'')}});
